from pathlib import Path
import html

R = Path(__file__).resolve().parents[2]
O = R / 'docs/reports/2026-10-10-whole-app-consistency'
O.mkdir(parents=True, exist_ok=True)

def table(headers, rows):
    return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'

def section(title, content, anchor=''):
    return '<section'+(' id="'+anchor+'"' if anchor else '')+'><h2>'+title+'</h2>'+content+'</section>'

def comparison(scene, title, before, after):
    return '<article class="comparison"><h3>'+title+'</h3><div class="compare-grid"><figure><img class="shot before" data-scene="'+scene+'" alt="Historical native '+scene+' screenshot"><figcaption><b>Current / retained native evidence</b><p>'+before+'</p></figcaption></figure><figure><img class="shot after" data-scene="'+scene+'" alt="Aligned HTML '+scene+' proposal"><figcaption><b>Refined HTML proposal</b><p>'+after+'</p><a href="prototype.html?screen='+scene+'" class="try">Try this screen →</a></figcaption></figure></div></article>'

